package com.mahesh.empleave.leave;
import com.mahesh.empleave.user.*;import jakarta.persistence.*;import lombok.*;import java.time.*;
@Entity @Table(name="leave_applications",indexes=@Index(name="ix_leave_applicant_dates",columnList="applicant_id,startDate,endDate")) @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED) public class LeaveApplication {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@ManyToOne(optional=false) private AppUser applicant;@Column(nullable=false) private String leaveType;@Column(nullable=false) private LocalDate startDate;@Column(nullable=false) private LocalDate endDate;@Column(nullable=false) private int workingDays;@Column(nullable=false) @Enumerated(EnumType.STRING) private LeaveStatus status=LeaveStatus.PENDING;private String reason;private String reviewerNote;@Version private Long version;public LeaveApplication(AppUser a,String t,LocalDate s,LocalDate e,int d,String r){applicant=a;leaveType=t;startDate=s;endDate=e;workingDays=d;reason=r;}public void approve(){if(status!=LeaveStatus.PENDING)throw new IllegalStateException("Only pending requests can be approved");status=LeaveStatus.APPROVED;}public void reject(String note){if(status!=LeaveStatus.PENDING)throw new IllegalStateException("Only pending requests can be rejected");status=LeaveStatus.REJECTED;reviewerNote=note;}public boolean cancel(){if(status==LeaveStatus.PENDING){status=LeaveStatus.CANCELLED;return false;}if(status==LeaveStatus.APPROVED&&startDate.isAfter(LocalDate.now())){status=LeaveStatus.CANCELLED;return true;}throw new IllegalStateException("This request cannot be cancelled");}}
